EN=["Maximum Power","Maximum Power Voltage","Maximum Power Current","Open Circuit Voltage","Short Circuit Current","Module Efficiency"]
def rows(P,rects,lim):
  for en,ar,r in zip(EN,ROWS,rects): P.add(en,r,ar,lim=lim)
def mech(P,title,labels,ar,en,lim):
  P.add("Mechanical Data",title,"البيانات الميكانيكية",lim=200)
  for e,a,r in zip(en,ar,labels): P.add(e,r,a,lim=lim)
def vals(P,lst,lim):
  for r,a in lst: P.add("(x)",r,a,lim=lim,maxfs=7.0)
def footer(P,contact,web,mail,made,bring,page):
  P.add("Contact Us for More Information",contact,"تواصل معنا لمزيد من المعلومات",b=True,lim=250)
  P.add("website: www.gclsi.com",web,"الموقع: www.gclsi.com",lim=web[2]+12)
  P.add("email:",mail,"البريد:",al="r",lim=999)
  P.add("Made in China",made,"صُنع في الصين",al="r",lim=999)
  P.add("Bringing Green Power To Life",bring,"نجلب الطاقة الخضراء إلى الحياة",al="c",lim=999)
  if page: P.add(page[0],page[1],page[2],b=True,al="r",lim=999)
